#include <iterator>
#include <sstream>
#include <vector>
#include <list>
#include <algorithm>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::vector<int> values{2, 3};
    std::back_insert_iterator back{values};
    *back = 4;
    ++back;
    back++;
    assert(values.back() == 4);
    std::list<int> list{2, 3};
    std::front_insert_iterator front{list};
    *front = 1;
    ++front;
    front++;
    assert(list.front() == 1);
    std::insert_iterator insert{values, values.begin()};
    *insert = 1;
    ++insert;
    insert++;
    assert(values.front() == 1);
    std::istringstream stream{"2 3"};
    std::istream_iterator<int> input{stream}, end;
    assert(input != end && *input == 2);
    ++input;
    assert(*input++ == 3);
    std::istringstream bytes{"abc"};
    std::istreambuf_iterator<char> byte{bytes}, byteEnd;
    assert(!byte.equal(byteEnd) && byte != byteEnd && *byte == 'a');
    assert(*byte++ == 'a');
    std::ostringstream output;
    std::ostream_iterator<int> out{output};
    *out++ = 7;
    ++out;
    std::ostreambuf_iterator<char> buffer{output};
    *buffer = 'x';
    ++buffer;
    buffer++;
    assert(!buffer.failed());
    assert(output.str() == "7x");
    int data[]{1, 2, 3};
    std::move_iterator<int *> moved{data}, copy;
    copy = moved;
    ++copy;
    copy += 1;
    copy -= 1;
    --copy;
    assert(copy == moved && moved + 1 == 1 + moved && moved + 2 - moved == 2);
    std::move_sentinel finish{data + 3};
    std::move_sentinel<int *> finishCopy;
    finishCopy = finish;
    assert(finishCopy.base() == data + 3 && finish - moved == 3);
    static_assert(std::is_same_v<std::incrementable_traits<int *>::difference_type,
        std::ptrdiff_t>);
    static_assert(
        std::is_same_v<std::indirectly_readable_traits<int *>::value_type, int>);
    static_assert(std::is_same_v<std::iter_value_t<int *>, int>);
    static_assert(std::is_same_v<std::iter_reference_t<int *>, int &>);
    assert(std::ranges::iter_move(data) == 1);
    std::ranges::iter_swap(data + 0, data + 1);
    assert(data[0] == 2);
}
